        h.destroy();
    p.handles = [];
}
async function revealHand(p) {
    if (!p.bot && solo)
        return;
    for (let k = 0; k < p.handles.length; k += 1) {
        const h = p.handles[k];
        let now = await h.refresh();
        if (!p.bot) {
            // Out of the hand and onto the felt, turned to its owner, as it lies now.
            h.setRotation([now && now.faceUp === false ? 180 : 0, textYaw(p.seat), 0]);
            h.setPosition(seatPoint(p.seat, CARD_X[k], ROW_ACTIONS, CARD_Y));
            await world.wait(0.2);
            now = await h.refresh();
        }
        if (now && now.faceUp === false)
            h.flip();
        h.lock();
    }
}
let waiter = null;
let waiterCounter = 0;
function waitForPress(seat, seconds, accept) {
    waiterCounter += 1;
    const id = waiterCounter;
    return new Promise((resolve) => {
        waiter = { accept, resolve, id, seat };
        void world.wait(Math.max(0.1, seconds)).then(() => {
            if (waiter && waiter.id === id) {
                waiter = null;
                resolve(null);
            }
        });
    });
}
function cancelWaiter() {
    if (!waiter)
        return;
    const w = waiter;
    waiter = null;
    w.resolve(null);
}
function handlePress(press) {
    if (waiter && waiter.accept(press)) {
        const w = waiter;
        waiter = null;
        w.resolve(press);
        return;
    }
    if (phase === "lobby")
        void handleLobbyPress(press);
}
globalEvents.onObjectAction.add((object, action, context) => {
    if (action !== "press")
        return;
    const config = object.metadata["button"];
    const name = config && typeof config.eventName === "string" ? config.eventName : "";
    if (!name.startsWith("hx:"))
        return;
    const parts = name.split(":");
    handlePress({
        kind: parts[1] || "",
        seat: Number(parts[2] || "-1"),
        nonce: parts[3] || "",
        arg: parts[4] || "",
        actorSeat: seatOfActor(context.actor)
    });
});
/** A seated player who walks away while it is their turn gives the turn up. */
function releaseIfGone() {
    if (!waiter || waiter.seat < 0 || solo)
        return;
    const p = seats[waiter.seat];
    if (!p || p.bot)
        return;
    const stillHere = world.getPlayers().some((entry) => entry.peerId === p.peerId && entry.seat === SEAT_IDS[p.seat]);
    if (!stillHere)
        cancelWaiter();
}
globalEvents.onPlayerLeft.add(() => { releaseIfGone(); if (phase === "lobby")
    void refreshLobby(); });
globalEvents.onSeatChanged.add(() => { releaseIfGone(); if (phase === "lobby")
    void refreshLobby(); });
globalEvents.onPlayerJoined.add(() => { if (phase === "lobby")
    void refreshLobby(); });
// ---------------------------------------------------------------- betting -----------
/**
 * Move chips from a player's rack into their bet. Pass the exact chips when the player
 * built the bet by hand; otherwise the rack pays, making change as it needs to.
 */
function commit(p, amount, chosen) {
    const paid = Math.max(0, Math.min(Math.round(amount), p.chips));
    const chipsOut = chosen && chipValue(chosen) === paid ? chosen : takeFromRack(p.inv, paid);
    addChips(p.pile, chipsOut);
    p.chips -= paid;
    p.bet += paid;
    p.total += paid;
    if (p.chips === 0)
        p.allIn = true;
    return paid;
}
/** Put the chips a player slid forward but did not bet back in their rack. */
function returnPending(p) {
    addChips(p.inv, p.pending);
    p.pending = noChips();
}
function contenders() {
    return occupied().filter((p) => p.inHand && !p.folded);
}
function canAct(p) {
    return p.inHand && !p.folded && !p.allIn;
}
function needsAction(p) {
    return canAct(p) && (!p.acted || p.bet < currentBet);
}
function roundToChip(n) {
    return Math.max(DENOMS[0], Math.round(n / DENOMS[0]) * DENOMS[0]);
}
function minimumRaiseTo() {
    return currentBet === 0 ? bigBlind : currentBet + minRaise;
}
function raiseChoices(p) {
    const maxTo = p.bet + p.chips;
    if (maxTo <= currentBet)
        return [];
    const minTo = minimumRaiseTo();
    const toCall = currentBet - p.bet;
    const potAfterCall = potTotal() + toCall;
    const wanted = [minTo, currentBet + roundToChip(potAfterCall / 2), currentBet + roundToChip(potAfterCall)];
    const out = [];
    for (const value of wanted) {
        if (value >= minTo && value < maxTo && out.indexOf(value) < 0)
            out.push(value);
    }
    out.sort((a, b) => a - b);
    return out.slice(0, 3);
}
function holeStrength(p) {
    if (p.cards.length < 2)
        return 0.3;
    const a = cardRank(p.cards[0]);
    const b = cardRank(p.cards[1]);
    const high = Math.max(a, b);
    const low = Math.min(a, b);
    if (board.length === 0) {
        if (a === b)
            return Math.min(1, 0.55 + a / 30);
        let s = ((high + low) / 28) * 0.62;
        if (cardSuit(p.cards[0]) === cardSuit(p.cards[1]))
            s += 0.06;
        if (high - low === 1)
            s += 0.05;
        if (high >= 13)
            s += 0.05;
        return s;
    }
    const mine = evaluate(p.cards.concat(board)).score[0];
    const shared = board.length >= 5 ? evaluate(board).score[0] : -1;
    if (mine === 0)
        return 0.12 + (high / 14) * 0.14;
    if (mine === shared)
        return 0.25;
    if (mine === 1)
        return 0.46 + (high / 14) * 0.08;
    if (mine === 2)
        return 0.66;
    if (mine === 3)
        return 0.76;
    if (mine === 4)
        return 0.83;
    if (mine === 5)
        return 0.87;
    return 0.96;
}
function botDecision(p) {
    const strength = holeStrength(p);
    const toCall = Math.max(0, currentBet - p.bet);
    const pot = potTotal();
    const roll = Math.random();
    const choices = raiseChoices(p);
    const maxTo = p.bet + p.chips;
    const pickRaise = () => {
        if (choices.length === 0)
            return maxTo;
        if (strength > 0.9 && roll < 0.25)
            return maxTo;
        return choices[Math.min(choices.length - 1, strength > 0.8 ? 1 : 0)];
    };
    if (toCall === 0) {
        if (strength > 0.62 && roll < 0.65)
            return { kind: "raise", to: pickRaise() };
        if (strength > 0.4 && roll < 0.18)
            return { kind: "raise", to: pickRaise() };
        if (roll < 0.05)
            return { kind: "raise", to: pickRaise() };
        return { kind: "call", to: currentBet };
    }
    const odds = toCall / (pot + toCall);
    const bigRisk = toCall > p.chips * 0.5;
    if (strength > 0.8) {
        if (roll < 0.55 && maxTo > currentBet)
            return { kind: "raise", to: pickRaise() };
        return { kind: "call", to: currentBet };
    }
    if (bigRisk && strength < 0.7)
        return { kind: "fold", to: 0 };
    if (strength > odds + 0.18 || strength > 0.5)
        return { kind: "call", to: currentBet };
    if (roll < 0.08)
        return { kind: "call", to: currentBet };
    return { kind: "fold", to: 0 };
}
/** The buttons a player gets on their turn: one "+" per stack, one "-" per pile chip, and the actions. */
async function showTurnButtons(p, nonce) {
    const seat = p.seat;
    const who = solo ? "any" : SEAT_IDS[seat];
    const yaw = textYaw(seat);
    const pendingTotal = chipValue(p.pending);
    const left = p.chips - pendingTotal;
    const toCall = Math.min(p.chips, Math.max(0, currentBet - p.bet));
    for (let k = 0; k < DENOMS.length; k += 1) {
        if (left >= DENOMS[k]) {
            await putButton({
                key: "act:plus" + k, text: "+", event: "hx:plus:" + seat + ":" + nonce + ":" + k,
                pos: seatPoint(seat, COLUMN_X[k], ROW_PLUS, BUTTON_Y), yaw, w: 0.09, d: 0.1, cap: "#15803d", who
            });
        }
        else {
            dropButton("act:plus" + k);
        }
        if (p.pending[k] > 0) {
            await putButton({
                key: "act:minus" + k, text: "-", event: "hx:minus:" + seat + ":" + nonce + ":" + k,
                pos: seatPoint(seat, COLUMN_X[k], ROW_MINUS, BUTTON_Y), yaw, w: 0.09, d: 0.1, cap: "#6b7280", who
            });
        }
        else {
            dropButton("act:minus" + k);
        }
    }
    const actions = [
        { key: "fold", text: "FOLD", kind: "fold", cap: "#b91c1c" },
        { key: "call", text: toCall === 0 ? "CHECK" : toCall >= p.chips ? "ALL IN" : "CALL " + toCall, kind: "call", cap: "#15803d" }
    ];
    const to = p.bet + pendingTotal;
    const allIn = pendingTotal === p.chips;
    if (pendingTotal > toCall && to > currentBet) {
        const legal = to >= minimumRaiseTo() || allIn;
        actions.push({
            key: "bet",
            text: legal ? (currentBet === 0 ? "BET " : "RAISE ") + to : "MIN " + minimumRaiseTo(),
            kind: legal ? "bet" : "short",
            cap: legal ? "#1d4ed8" : "#374151"
        });
    }
    if (p.chips > toCall && !allIn) {
        actions.push({ key: "allin", text: "ALL IN", kind: "allin", cap: "#7e22ce" });
    }
    // One row centred on the seat, FOLD at the player's left. A seat's +lx is its player's
    // left, so the row is laid out from the high end down. Narrow enough that four buttons
    // stay inside the seat's own printed area.
    const pitch = 0.3;
    const live = {};
    for (let n = 0; n < actions.length; n += 1) {
        live[actions[n].key] = true;
        await putButton({
            key: "act:" + actions[n].key, text: actions[n].text, event: "hx:" + actions[n].kind + ":" + seat + ":" + nonce,
            pos: seatPoint(seat, ((actions.length - 1) / 2 - n) * pitch, ROW_ACTIONS, BUTTON_Y), yaw, w: 0.27, d: 0.15, cap: actions[n].cap, who
        });
    }
    for (const key of ["fold", "call", "bet", "allin"])
        if (!live[key])
            dropButton("act:" + key);
}
async function humanDecision(p) {
    turnNonce += 1;
    const nonce = "n" + turnNonce;
    const seat = p.seat;
    const toCall = Math.min(p.chips, Math.max(0, currentBet - p.bet));
    // The chips it takes to call start in the pile, so a raise is just adding more chips to it.
    p.pending = takeFromRack(p.inv, toCall);
    let secondsLeft = TURN_SECONDS;
    for (let guard = 0; guard < 400; guard += 1) {
        await renderChips();
        await showTurnButtons(p, nonce);
        const startedAt = Date.now();
        const press = await waitForPress(seat, secondsLeft, (candidate) => candidate.seat === seat && candidate.nonce === nonce && (solo || candidate.actorSeat === seat));
        secondsLeft -= (Date.now() - startedAt) / 1000;
        if (!press) {
            dropButtons("act:");
            returnPending(p);
            world.broadcast(p.name + " ran out of time.");
            return toCall === 0 ? { kind: "call", to: currentBet } : { kind: "fold", to: 0 };
        }
        const k = Number(press.arg);
        if (press.kind === "plus" && k >= 0 && k < DENOMS.length) {
            if (p.chips - chipValue(p.pending) >= DENOMS[k]) {
                takeFromRack(p.inv, DENOMS[k]);
                p.pending[k] += 1;
            }
            continue;
        }
        if (press.kind === "minus" && k >= 0 && k < DENOMS.length) {
            if (p.pending[k] > 0) {
                p.pending[k] -= 1;
                p.inv[k] += 1;
            }
            continue;
        }
        if (press.kind === "short")
            continue;
        dropButtons("act:");
        const built = p.pending;
        const builtTotal = chipValue(built);
        if (press.kind === "fold") {
            returnPending(p);
            return { kind: "fold", to: 0 };
        }
        if (press.kind === "allin") {
            returnPending(p);
            return { kind: "raise", to: p.bet + p.chips };
        }
        if (press.kind === "bet" && builtTotal > toCall) {
            p.pending = noChips();
            return { kind: "raise", to: p.bet + builtTotal, chips: built };
        }
        if (builtTotal === toCall) {
            p.pending = noChips();
            return { kind: "call", to: currentBet, chips: built };
        }
        returnPending(p);
        return { kind: "call", to: currentBet };
    }
    dropButtons("act:");
    returnPending(p);
    return { kind: "fold", to: 0 };
}
function applyDecision(p, decision) {
    const toCall = Math.max(0, currentBet - p.bet);
    if (decision.kind === "fold") {
        p.folded = true;
        p.note = "FOLD";
        muck(p);
        world.broadcast(p.name + " folds.");
        return;
    }
    if (decision.kind === "call" || decision.to <= currentBet) {
        if (toCall === 0) {
            p.note = "CHECK";
            world.broadcast(p.name + " checks.");
        }
        else {
            const paid = commit(p, toCall, decision.chips);
            p.note = p.allIn ? "ALL-IN " + p.bet : "CALL " + p.bet;
            world.broadcast(p.name + (p.allIn ? " is all in for " + money(p.bet) + "." : " calls " + money(paid) + "."));
        }
        return;
    }
    const opening = currentBet === 0;
    commit(p, decision.to - p.bet, decision.chips);
    const raisedBy = p.bet - currentBet;
    if (raisedBy >= minRaise) {
        minRaise = raisedBy;
        for (const other of occupied())
            if (other !== p)
                other.acted = false;
    }
    if (p.bet > currentBet)
        currentBet = p.bet;
    p.note = p.allIn ? "ALL-IN " + p.bet : (opening ? "BET " : "RAISE ") + p.bet;
    world.broadcast(p.name + (p.allIn ? " moves all in for " + money(p.bet) + "." : opening ? " bets " + money(p.bet) + "." : " raises to " + money(p.bet) + "."));
}
async function bettingRound(firstSeat) {
    let cursor = (firstSeat + 9) % 10;
    for (let guard = 0; guard < 200; guard += 1) {
        if (contenders().length <= 1)
            break;
        const seat = nextSeat(cursor, needsAction);
        if (seat < 0)
            break;
        const p = seats[seat];
        if (!p)
            break;
        const others = contenders().filter((q) => q !== p && !q.allIn);
        if (others.length === 0 && p.bet >= currentBet)
            break;
        activeSeat = seat;
        const toCall = Math.max(0, currentBet - p.bet);
        statusText = shortName(p.name) + " to act - " + (toCall > 0 ? money(toCall) + " to call" : "check or bet");
        await render();
        let decision;
        if (p.bot) {
            await world.wait(0.9 + Math.random() * 0.9);
            decision = botDecision(p);
        }
        else {
            decision = await humanDecision(p);
        }
        applyDecision(p, decision);
        p.acted = true;
        cursor = seat;
    }
    activeSeat = -1;
    await render();
}
/** The round's bets leave the players' piles and join the pot in the middle. */
function gatherBets() {
    for (const p of occupied()) {
        p.bet = 0;
        p.pile = noChips();
    }
    potOnTable = potTotal();
}
function startStreet() {
    gatherBets();
    for (const p of occupied()) {
        p.acted = false;
        if (p.inHand && !p.folded && !p.allIn)
            p.note = "";
    }
    currentBet = 0;
    minRaise = bigBlind;
}
function buildPots() {
    const everyone = occupied().filter((p) => p.total > 0);
    const levels = [];
    for (const p of everyone)
        if (levels.indexOf(p.total) < 0)
            levels.push(p.total);
    levels.sort((a, b) => a - b);
    const pots = [];
    let previous = 0;
    for (const level of levels) {
        let amount = 0;
        for (const p of everyone)
            amount += Math.min(p.total, level) - Math.min(p.total, previous);
        const eligible = everyone.filter((p) => !p.folded && p.total >= level);
        if (amount > 0) {
            if (eligible.length === 0 && pots.length > 0) {
                pots[pots.length - 1].amount += amount;
            }
            else {
                const last = pots.length > 0 ? pots[pots.length - 1] : null;
                if (last && last.eligible.length === eligible.length && last.eligible.every((p) => eligible.indexOf(p) >= 0)) {
                    last.amount += amount;
                }
                else {
                    pots.push({ amount, eligible });
                }
            }
        }
        previous = level;
    }
    return pots;
}
async function settleHand() {
    const live = contenders();
    const winnings = {};
    let headline = "";
    if (live.length === 1) {
        const winner = live[0];
        winnings[winner.seat] = potTotal();
        headline = shortName(winner.name) + " wins " + money(potTotal());
        world.broadcast(winner.name + " wins " + money(potTotal()) + " - everyone else folded.");
    }
    else {
        statusText = "Showdown";
        await render();
        const values = {};
        for (const p of live) {
            await revealHand(p);
            values[p.seat] = evaluate(p.cards.concat(board));
            world.broadcast(p.name + " shows " + p.cards.map(cardName).join(" ") + " - " + values[p.seat].name + ".");
        }
        await world.wait(1.2);
        const pots = buildPots();
        for (const pot of pots) {
            if (pot.eligible.length === 0)
                continue;
            let best = pot.eligible[0];
            for (const p of pot.eligible)
                if (compareScores(values[p.seat].score, values[best.seat].score) > 0)
                    best = p;
            const winners = pot.eligible.filter((p) => compareScores(values[p.seat].score, values[best.seat].score) === 0);
            // Split in whole chips; the odd chips go to the first winners left of the dealer.
            const unit = DENOMS[0];
            const share = Math.floor(pot.amount / winners.length / unit) * unit;
            let spare = pot.amount - share * winners.length;
            let cursor = dealer;
            for (let n = 0; n < 10 && spare > 0; n += 1) {
                cursor = (cursor + 1) % 10;
                const lucky = winners.find((p) => p.seat === cursor);
                if (lucky) {
                    const extra = Math.min(unit, spare);
                    winnings[lucky.seat] = (winnings[lucky.seat] || 0) + extra;
                    spare -= extra;
                }
            }
            for (const p of winners)
                winnings[p.seat] = (winnings[p.seat] || 0) + share;
            if (pot.eligible.length > 1) {
                world.broadcast(winners.map((p) => p.name).join(" and ") + (winners.length > 1 ? " split " : " wins ") + money(pot.amount) + " with " + values[best.seat].name + ".");
                if (headline.length === 0) {
                    headline = winners.length > 1 ? "Split pot - " + values[best.seat].label : shortName(best.name) + " wins - " + values[best.seat].label;
                }
            }
        }
        if (headline.length === 0)
            headline = "Hand complete";
    }
    for (const p of occupied()) {
        const won = winnings[p.seat] || 0;
        if (won > 0) {
            p.chips += won;
            addChips(p.inv, fewestChips(won));
            if (p.inHand && !p.folded)
                p.note = "WIN " + money(won);
        }
        p.total = 0;
        p.bet = 0;
        p.pile = noChips();
    }
    potOnTable = 0;
    statusText = headline;
    await render();
}
// ---------------------------------------------------------------- one hand ----------
async function playHand() {
    phase = "hand";
    handNo += 1;
    board = [];
    potOnTable = 0;
    dropButtons("lobby:");
    dropButtons("deal:");
    for (const p of occupied()) {
        p.bet = 0;
        p.total = 0;
        p.folded = false;
        p.allIn = false;
        p.acted = false;
        p.cards = [];
        p.handles = [];
        p.note = "";
        p.pile = noChips();
        p.pending = noChips();
        // Re-rack between hands, so everyone starts with small chips to bet with.
        p.inv = rackChips(p.chips);
        p.inHand = p.chips > 0;
    }
    const inHand = (p) => p.inHand;
    dealer = nextSeat(dealer, inHand);
    const count = occupied().filter(inHand).length;
    const smallSeat = count === 2 ? dealer : nextSeat(dealer, inHand);
    const bigSeat = nextSeat(smallSeat, inHand);
    statusText = "Hand " + handNo + " - shuffling";
    await render();
    if (!(await freshDeck())) {
        world.broadcast("The deck could not be set up.");
        stopRequested = true;
        return;
    }
    const small = seats[smallSeat];
    const big = seats[bigSeat];
    const level = BLIND_LEVELS[Math.min(BLIND_LEVELS.length - 1, Math.floor((handNo - 1) / HANDS_PER_LEVEL))];
    if (level[1] !== bigBlind && handNo > 1)
        world.broadcast("Blinds go up to " + level[0] + "/" + level[1] + ".");
    smallBlind = level[0];
    bigBlind = level[1];
    if (small) {
        commit(small, smallBlind);
        small.note = "SB " + small.bet;
    }
    if (big) {
        commit(big, bigBlind);
        big.note = "BB " + big.bet;
    }
    currentBet = bigBlind;
    minRaise = bigBlind;
    world.broadcast("Hand " + handNo + ": " + (seats[dealer] ? seats[dealer].name : "?") + " has the dealer button. Blinds " + smallBlind + "/" + bigBlind + ".");
    statusText = "Hand " + handNo + " - blinds " + smallBlind + "/" + bigBlind;
    await render();
    for (let round = 0; round < 2; round += 1) {
        let seat = dealer;
        for (let n = 0; n < count; n += 1) {
            seat = nextSeat(seat, inHand);
            const p = seats[seat];
            if (p)
                await dealHoleCard(p, round);
            await world.wait(0.12);
        }
    }
    await bettingRound(nextSeat(bigSeat, inHand));
    const streets = [3, 1, 1];
    const streetNames = ["Flop", "Turn", "River"];
    for (let s = 0; s < streets.length; s += 1) {
        if (contenders().length <= 1)
            break;
        startStreet();
        statusText = streetNames[s];
        await render();
        await dealCommunity(streets[s]);
        world.broadcast(streetNames[s] + ": " + board.map(cardName).join(" "));
        if (contenders().filter((p) => !p.allIn).length >= 2) {
            await bettingRound(nextSeat(dealer, (p) => p.inHand && !p.folded));
        }
        else {
            await world.wait(1);
        }
    }
    gatherBets();
    await render();
    await settleHand();
    for (const p of occupied())
        p.inHand = false;
    await saveGame();
}
// ---------------------------------------------------------------- between hands -----
function announceWinner() {
    const funded = occupied().filter((p) => p.chips > 0);
    if (funded.length >= 2)
        return false;
    if (funded.length === 1)
        world.broadcast(funded[0].name + " wins the game with " + money(funded[0].chips) + "!");
    statusText = funded.length === 1 ? shortName(funded[0].name) + " wins the game!" : "Game over";
    return true;
}
async function betweenHands() {
    phase = "between";
    await world.wait(3);
    syncRoster();
    for (let i = 0; i < 10; i += 1) {
        const p = seats[i];
        if (p && p.bot && p.chips === 0) {
            world.broadcast(p.name + " is out of chips and leaves the table.");
            seats[i] = null;
            botTarget = Math.max(0, botTarget - 1);
        }
    }
    const funded = occupied().filter((p) => p.chips > 0);
    const broke = occupied().filter((p) => p.chips === 0 && !p.bot);
    if (broke.length === 0 && announceWinner())
        return false;
    const nextDealer = funded.length >= 2 ? nextSeat(dealer, (p) => p.chips > 0) : -1;
    const dealerPlayer = nextDealer >= 0 ? seats[nextDealer] : null;
    for (const p of broke) {
        await putButton({
            key: "deal:rebuy" + p.seat, text: "REBUY " + START_CHIPS, event: "hx:rebuy:" + p.seat + ":x",
            pos: seatPoint(p.seat, 0.3, ROW_PLUS, BUTTON_Y), yaw: textYaw(p.seat), w: 0.44, d: 0.15, cap: "#7e22ce",
            who: solo ? "any" : SEAT_IDS[p.seat]
        });
    }
    await putButton({ key: "deal:end", text: "END GAME", event: "hx:end:-1:x", pos: [1.0, BUTTON_Y, -1.14], yaw: 0, w: 0.4, d: 0.15, cap: "#6b7280", who: "any" });
    let autoSeconds = DEAL_WAIT_SECONDS;
    if (dealerPlayer) {
        if (dealerPlayer.bot) {
            autoSeconds = 5;
        }
        else {
            await putButton({
                key: "deal:go", text: "DEAL", event: "hx:deal:" + nextDealer + ":x",
                pos: seatPoint(nextDealer, 0.1, ROW_ACTIONS, BUTTON_Y), yaw: textYaw(nextDealer), w: 0.34, d: 0.15, cap: "#b45309",
                who: solo ? "any" : SEAT_IDS[nextDealer]
            });
        }
    }
    else {
        statusText = "Out of chips - REBUY to go on";
        autoSeconds = 120;
    }
    await render();
    for (let guard = 0; guard < 40; guard += 1) {
        const press = await waitForPress(-1, autoSeconds, (candidate) => candidate.kind === "end"
            || (candidate.kind === "deal" && (solo || candidate.actorSeat === candidate.seat))
            || (candidate.kind === "rebuy" && (solo || candidate.actorSeat === candidate.seat)));
        if (press && press.kind === "end") {
            dropButtons("deal:");
            statusText = "Game ended";
            return false;
        }
        if (press && press.kind === "rebuy") {
            const p = seats[press.seat];
            if (p && p.chips === 0) {
                setChips(p, START_CHIPS);
                p.note = "";
                world.broadcast(p.name + " buys back in for " + money(START_CHIPS) + ".");
            }
            dropButton("deal:rebuy" + press.seat);
            await render();
            if (occupied().filter((q) => q.chips > 0).length >= 2 && !dealerPlayer)
                break;
            continue;
        }
        break;
    }
    dropButtons("deal:");
    syncRoster();
    return !announceWinner();
}
// ---------------------------------------------------------------- lobby -------------
async function saveGame() {
    const stacks = {};
    const bots = [];
    for (const p of occupied()) {
        stacks[SEAT_IDS[p.seat]] = p.chips;
        if (p.bot)
            bots.push(p.seat);
    }
    await world.setSavedData(JSON.stringify({ active: running && !stopRequested, stacks, bots, dealer, handNo }), "holdem");
}
async function loadGame() {
    savedGame = null;
    const raw = await world.getSavedData("holdem");
    if (!raw)
        return;
    try {
        const data = JSON.parse(raw);
        if (data.active && data.stacks) {
            savedGame = { stacks: data.stacks, bots: data.bots || [], dealer: data.dealer === undefined ? -1 : data.dealer, handNo: data.handNo || 0 };
        }
    }
    catch (error) {
        savedGame = null;
    }
}
async function refreshLobby() {
    if (phase !== "lobby")
        return;
    if (lobbyBusy) {
        lobbyDirty = true;
        return;
    }
    lobbyBusy = true;
    lobbyDirty = false;
    syncRoster();
    const count = occupied().length;
    for (const p of occupied())
        p.note = p.bot ? "BOT" : "READY";
    if (bannerText.length > 0)
        statusText = bannerText;
    else if (solo)
        statusText = count >= 2 ? "Practice table - press START" : "Practice table - add bots, then START";
    else if (count >= 2)
        statusText = count + " players ready - press START";
    else
        statusText = "Take a seat - 2 or more players, or add bots";
    await putButton({ key: "lobby:start", text: "START GAME", event: "hx:start:-1:x", pos: [0, BUTTON_Y, -1.14], yaw: 0, w: 0.5, d: 0.15, cap: "#15803d", who: "any" });
    await putButton({ key: "lobby:addbot", text: "+ BOT", event: "hx:addbot:-1:x", pos: [-0.52, BUTTON_Y, -1.14], yaw: 0, w: 0.3, d: 0.15, cap: "#1d4ed8", who: "any" });
    await putButton({ key: "lobby:delbot", text: "- BOT", event: "hx:delbot:-1:x", pos: [0.52, BUTTON_Y, -1.14], yaw: 0, w: 0.3, d: 0.15, cap: "#6b7280", who: "any" });
    if (savedGame) {
        await putButton({ key: "lobby:resume", text: "RESUME", event: "hx:resume:-1:x", pos: [1.0, BUTTON_Y, -1.14], yaw: 0, w: 0.36, d: 0.15, cap: "#b45309", who: "any" });
    }
    else {
        dropButton("lobby:resume");
    }
    await render();
    lobbyBusy = false;
    if (lobbyDirty && phase === "lobby")
        await refreshLobby();
}
async function handleLobbyPress(press) {
    if (running)
        return;
    bannerText = "";
    if (press.kind === "addbot") {
        syncRoster();
        const humans = occupied().filter((p) => !p.bot).length;
        if (botTarget < MAX_BOTS && humans + botTarget < 10)
            botTarget += 1;
        await refreshLobby();
        return;
    }
    if (press.kind === "delbot") {
        if (botTarget > 0)
            botTarget -= 1;
        await refreshLobby();
        return;
    }
    if (press.kind === "start" || press.kind === "resume") {
        syncRoster();
        if (press.kind === "resume" && savedGame) {
            botTarget = savedGame.bots.length;
            for (const seat of savedGame.bots) {
                if (!seats[seat])
                    seats[seat] = newPlayer(seat, "bot-" + seat, true, BOT_NAMES[seat], START_CHIPS);
            }
            for (const p of occupied()) {
                const stack = savedGame.stacks[SEAT_IDS[p.seat]];
                if (typeof stack === "number")
                    setChips(p, stack);
            }
            dealer = savedGame.dealer;
            handNo = savedGame.handNo;
        }
        else {
            for (const p of occupied())
                setChips(p, START_CHIPS);
            dealer = Math.floor(Math.random() * 10);
            handNo = 0;
        }
        if (occupied().filter((p) => p.chips > 0).length < 2) {
            bannerText = "Need 2 players - take seats or press + BOT";
            await refreshLobby();
            return;
        }
        savedGame = null;
        void runGame();
    }
}
async function runGame() {
    if (running)
        return;
    running = true;
    stopRequested = false;
    dropButtons("lobby:");
    for (const p of occupied())
        p.note = "";
    world.broadcast("Texas Hold'em: " + occupied().length + " players, " + money(START_CHIPS) + " each. Blinds start at " + BLIND_LEVELS[0][0] + "/" + BLIND_LEVELS[0][1] + " and rise every " + HANDS_PER_LEVEL + " hands.");
    for (let guard = 0; guard < 100000; guard += 1) {
        await playHand();
        if (stopRequested)
            break;
        const again = await betweenHands();
        if (!again)
            break;
    }
    running = false;
    phase = "lobby";
    dealer = -1;
    activeSeat = -1;
    potOnTable = 0;
    dropButtons("deal:");
    dropButtons("act:");
    for (const p of occupied()) {
        p.note = "";
        p.inHand = false;
        p.pile = noChips();
        p.pending = noChips();
        p.inv = rackChips(p.chips);
    }
    bannerText = statusText;
    await saveGame();
    await refreshLobby();
}
async function boot() {
    const oldUi = await world.getAllObjects({ tag: TAG_UI });
    for (const h of oldUi)
        h.destroy();
    const oldChips = await world.getAllObjects({ tag: TAG_CHIP });
    for (const h of oldChips)
        h.destroy();
    // The deck the scene was saved with is swapped for the one the game deals.
    await freshDeck(false);
    await loadGame();
    await refreshLobby();
    world.log("Texas Hold'em ready.");
}
void boot();
